package com.testforge.testforge_backend.exception;
import com.testforge.testforge_backend.automation.exception.AutomationNotFoundException; import org.junit.jupiter.api.Test; import org.springframework.web.bind.annotation.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class GlobalAutomationExceptionHandlerTest {
 @RestController static class FailureController {@GetMapping("/suite-failure") void fail(){throw new AutomationNotFoundException("Test Case \"Login\" (TC-1) has no automation script configured.");}@GetMapping("/plan-conflict") void conflict(){throw new TestPlanInUseException("Test Plan cannot be deleted because it contains Modules or test design data.");}}
 @Test void mapsAutomationNotFoundOutsideAutomationControllersToStructured404()throws Exception{MockMvcBuilders.standaloneSetup(new FailureController()).setControllerAdvice(new GlobalExceptionHandler()).build().perform(get("/suite-failure")).andExpect(status().isNotFound()).andExpect(jsonPath("$.status").value(404)).andExpect(jsonPath("$.error").value("Not Found")).andExpect(jsonPath("$.message").value("Test Case \"Login\" (TC-1) has no automation script configured.")).andExpect(jsonPath("$.path").value("/suite-failure")).andExpect(jsonPath("$.timestamp").exists());}
 @Test void mapsTestPlanDependencyToStructured409()throws Exception{MockMvcBuilders.standaloneSetup(new FailureController()).setControllerAdvice(new GlobalExceptionHandler()).build().perform(get("/plan-conflict")).andExpect(status().isConflict()).andExpect(jsonPath("$.status").value(409)).andExpect(jsonPath("$.message").value("Test Plan cannot be deleted because it contains Modules or test design data.")).andExpect(jsonPath("$.path").value("/plan-conflict"));}
}
